sc_cat_item_producer.script:
// ---- 0. Ownership check: customers can only claim against their own policy ----
var enteredPolicy = (producer.policy_number_text || '').toString().trim();
var policyGr = new GlideRecord('x_snc_insurance_0_policy');
policyGr.addQuery('policy_number', enteredPolicy);
policyGr.setLimit(1);
policyGr.query();

var policyOk = false;
if (policyGr.next()) {
    var isStaff = gs.hasRole('admin') || gs.hasRole('x_snc_insurance_0.policy_user');
    policyOk = isStaff || policyGr.getValue('policy_owner') == gs.getUserID();
}

if (!policyOk) {
    gs.addErrorMessage('This policy number is not linked to your account. Please check it and try again.');
    current.setAbortAction(true);
} else {
    // The Claim's Policy Number is a reference field, so store the policy record itself
    current.setValue('policy_number', policyGr.getUniqueValue());

    // ---- 1. System-controlled claim fields ----
    current.setValue('submitted_by', gs.getUserID());
    var now = new GlideDateTime().getValue();
    current.setValue('date_of_submission', now);
    current.setValue('last_updated', now);
    current.setValue('claim_status', 'submitted');

    // Create a linked Customer Service Case for this claim
    var caseGr = new GlideRecord('sn_customerservice_case');
    caseGr.initialize();
    caseGr.setValue('short_description', 'Insurance claim - ' + current.getValue('claim_type') + ' - ' +
        current.getValue('short_description'));
    caseGr.setValue('description', 'Auto-created for claim ' + current.getValue('number') +
        '. Claim type: ' + current.getValue('claim_type') +
        '. Date of incident: ' + current.getValue('date_of_incident'));

    // Look up this user's Consumer record (the correct B2C ownership link for CSM)
    var consumer = new GlideRecord('csm_consumer');
    consumer.addQuery('user', gs.getUserID());
    consumer.query();
    if (consumer.next()) {
        caseGr.setValue('consumer', consumer.getUniqueValue());
    } else {
        // Fallback for internal/admin test submissions with no Consumer record
        caseGr.setValue('contact', gs.getUserID());
        caseGr.setValue('account', gs.getUserID());
    }
    var adjusterGroup = new GlideRecord('sys_user_group');
    if (adjusterGroup.get('name', 'Claims Adjusters')) {
        caseGr.setValue('assignment_group', adjusterGroup.getUniqueValue());
    }
    caseGr.comments = 'We have received your claim and are checking it now. We will keep you updated here.';
    var caseSysId = caseGr.insert();



    current.setValue('customer_case', caseSysId);
    producer.portal_redirect = '?id=csm_ticket&table=sn_customerservice_case&sys_id=' + caseSysId;


    // ---- 2. Give the claim its ID now, so documents can link to it ----
    // The form saves the claim itself right after this script, so no current.insert() here.
    var claimSysId = gs.generateGUID();
    current.setNewGuidValue(claimSysId);

    // ---- 3. Which documents are mandatory for this claim type? ----
    var mandatory = {};
    var rule = new GlideRecord('x_snc_insurance_0_claim_type_document_rules');
    rule.addQuery('claim_type', current.getValue('claim_type'));
    rule.addQuery('is_mandatory', true);
    rule.query();
    while (rule.next()) {
        mandatory[rule.getValue('required_document_type')] = true;
    }

    // ---- 4. Create Document records ----
    // Uploaded file -> "uploaded" record with the file copied onto it
    // Mandatory but not uploaded -> "missing" placeholder
    // Not uploaded and not needed for this claim type -> skipped
    var docTypes = ['claim_form', 'police_report', 'repair_invoice', 'id_proof',
        'medical_report', 'property_photos', 'incident_report', 'travel_itinerary'
    ];

    for (var i = 0; i < docTypes.length; i++) {
        var docType = docTypes[i];
        var value = producer['doc_' + docType];
        var attachmentId = value ? value.toString() : '';

        if (!attachmentId && !mandatory[docType]) {
            continue;
        }

        var doc = new GlideRecord('x_snc_insurance_0_document');
        doc.initialize();
        doc.setValue('claim_id', claimSysId);
        doc.setValue('document_type', docType);

        if (attachmentId) {
            doc.setValue('upload_status', 'uploaded');
            doc.setValue('uploaded_date', now);
            doc.insert();

            // Copy exactly this customer's file onto the Document record
            try {
                var att = new GlideRecord('sys_attachment');
                if (att.get(attachmentId)) {
                    var gsa = new GlideSysAttachment();
                    gsa.writeContentStream(doc, att.getValue('file_name'),
                        att.getValue('content_type'), gsa.getContentStream(attachmentId));
                }
            } catch (e) {
                gs.warn('Could not copy file for ' + docType + ': ' + e);
            }
        } else {
            doc.setValue('upload_status', 'missing');
            doc.insert();
        }
    }
}
